{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE cp_2 as( select * from ( SELECT *, CASE WHEN DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE) > MAX_SLA THEN \'breach\' ELSE \'non-breach\' END AS breach_flag, (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) AS breach_date, CASE WHEN (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) < -2 THEN \'-3\' WHEN (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) = -2 THEN \'-2\' WHEN (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) = -1 THEN \'-1\' WHEN (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) = 0 THEN \'0\' WHEN (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) = 1 THEN \'1\' WHEN (DATEDIFF(\'day\', DATE_TRUNC(\'day\', OUTFORDELIVERY_DATE), MAX_SLA) * -1) = 2 THEN \'2\' ELSE \'3\' END AS breach_date_category, (DATEDIFF(\'hour\', OUTFORDELIVERY_DATE, MAX_SLA) * -1) AS breach_hours, DATEDIFF(\'hour\', PICKUP_DATE, OUTFORDELIVERY_DATE) AS actual_sla_shipping_hrs, DATEDIFF(\'day\', PICKUP_DATE, OUTFORDELIVERY_DATE) AS actual_sla_shipping_days, DATEDIFF(\'hour\', ORDER_DATE, OUTFORDELIVERY_DATE) AS actual_sla_delivery_hrs, DATEDIFF(\'day\', ORDER_DATE,OUTFORDELIVERY_DATE ) AS actual_sla_delivery_days, DATEDIFF(\'hour\', ORDER_DATE, delivery_date) AS actual_sla_delivered_hrs, DATEDIFF(\'day\', ORDER_DATE,delivery_date ) AS actual_sla_delivered_days, DATEDIFF(\'day\',PICKUP_DATE,MAX_SLA) AS predicted_tat FROM cp_1 where order_date > \'2024-07-01\' AND status = \'DELIVERED\' AND JOURNEY= \'Forward\' )A left join ( select * from ( SELECT ZONE AS Zone_m, City_Tier AS City_Tier, Delivery_Postcode, ROW_NUMBER() OVER (PARTITION BY Delivery_Postcode ORDER BY 1) AS rn FROM snitch_db.maplemonk.pincodemappingzoneupdatedsnitch ) WHERE rn=1) B on A.PINCODE = B.DELIVERY_POSTCODE ); CREATE OR REPLACE TABLE cp_4 as ( select * from ( WITH weekly_pincode_volume AS ( SELECT PINCODE, DATE_TRUNC(\'WEEK\', OUTFORDELIVERY_DATE) AS week, COUNT(*) AS order_count, COUNT(CASE WHEN breach_flag = \'breach\' THEN 1 END) AS breach_count FROM cp_2 GROUP BY PINCODE, DATE_TRUNC(\'WEEK\', OUTFORDELIVERY_DATE) ), ranked_pincodes AS ( SELECT PINCODE, week, order_count, order_count::FLOAT / SUM(order_count) OVER (PARTITION BY week) AS pincode_weekly_percentage, breach_count, (breach_count::FLOAT / order_count) * 100 AS breach_percentage FROM weekly_pincode_volume ), pincode_percentage AS ( SELECT PINCODE, week, order_count, breach_percentage, SUM(pincode_weekly_percentage) OVER (PARTITION BY week ORDER BY pincode_weekly_percentage DESC, PINCODE) AS cumulative_percentage FROM ranked_pincodes ) SELECT PINCODE, week, order_count, cumulative_percentage,breach_percentage, CASE WHEN cumulative_percentage <= 0.10 THEN \'top10%\' WHEN cumulative_percentage > 0.10 AND cumulative_percentage <= 0.20 THEN \'top10-20%\' WHEN cumulative_percentage > 0.20 AND cumulative_percentage <= 0.30 THEN \'top20-30%\' WHEN cumulative_percentage > 0.30 AND cumulative_percentage <= 0.40 THEN \'top30-40%\' WHEN cumulative_percentage > 0.40 AND cumulative_percentage <= 0.50 THEN \'top40-50%\' WHEN cumulative_percentage > 0.50 AND cumulative_percentage <= 0.60 THEN \'top50-60%\' WHEN cumulative_percentage > 0.60 AND cumulative_percentage <= 0.70 THEN \'top60-70%\' WHEN cumulative_percentage > 0.70 AND cumulative_percentage <= 0.80 THEN \'top70-80%\' WHEN cumulative_percentage > 0.80 AND cumulative_percentage <= 0.90 THEN \'top80-90%\' ELSE \'top90-100%\' END AS pincode_category FROM pincode_percentage ORDER BY week, cumulative_percentage ) where week is not null ); CREATE OR REPLACE TABLE cp_5 as ( select *,\"Created at\"::timestamp as Created_at from snitch_clickpost_track_order_dashboard_report where \"Courier Partner\" in (\'Delhivery Reverse\',\'Proship B2C Reverse\',\'Ekart Reverse\') and \"Created at\" >= \'2024-10-01 00:00:00\' and \"Out For Pickup Attempts\" IS NOT NULL AND \"Out For Pickup Attempts\" != \'\' AND \"Out For Pickup Attempts\" != \'0\' AND \"Out For Pickup Attempts\" != \'1\' ); CREATE OR REPLACE TABLE cp_6 AS ( SELECT \"Account Code\",AWB,ZONE,\"QC Type\",\"RTO AWB\",\"Order ID\",\"Created at\",\"Created at\"::timestamp as Created_at ,\"Order Date\",\"RVP Reason\",\"Drop Pincode\",\"Payment Mode\",\"Committed SLA\",\"Delivery Date\",\"Latest Remark\",\"RTO Mark Date\",\"Pickup Pincode\",\"Return Pincode\",\"Courier Partner\",\"OTP Verified Delivery\",\"Remark Of Last Pickup\",\"Out For Pickup Attempts\",\"Clickpost Unified Status\",\"OTP Verified Cancellation\",\"Out For Delivery Attempts\",\"Out For Pickup 1st Attempt\",\"Out For Pickup 2nd Attempt\",\"Out For Pickup 3rd Attempt\",\"Out For Delivery 1st Attempt\",\"Out For Delivery 2nd Attempt\",\"Out For Delivery 3rd Attempt\",\"Out For Delivery 4th Attempt\",\"Out For Delivery 5th Attempt\",\"Reason For Last Failed Pickup\",\"Remark Of First Failed Pickup\",\"Reason For First Failed Pickup\",\"Remark Of Last Failed Delivery\",\"Expected Date of Delivery (Max)\",\"Expected Date of Delivery (Min)\",\"Reason For Last Failed Delivery\",\"Remark Of First Failed Delivery\",\"TimeStamp Of Last Failed Pickup\",\"Reason For First Failed Delivery\",\"TimeStamp Of First Failed Pickup\",\"TimeStamp Of Last Failed Delivery\",\"TimeStamp Of First Failed Delivery\",\"Pickup Date\" FROM snitch_clickpost_track_order_dashboard_report where \"Created at\" >= \'2024-10-01\' ) ; CREATE OR REPLACE TABLE customer_support_escalations as ( WITH A AS ( SELECT *, CASE WHEN TAG IN ( \'Where is my order\',\'Delay_Delivery\',\'RTO\',\'My order EDD\',\'POD\', \'Tracking_Link_Status\',\'EMIZA\',\'WH2\',\'Is my order confirmed?\', \'Manifest-Issue\',\'NSPC_forward\',\'Dispatch_Delay\',\'Shipment_Lost\',\'In TAT - Where is my order\',\'Out TAT - Delay_Delivery\' ) THEN \'Forward\' WHEN TAG IN ( \'Refund_Query_Within_TAT\',\'Refund_not_Initiated\',\'General_refund_query\', \'Wallet_Refund_Query\',\'UTR\',\'Wallet_to_Refund\',\'Giftcard_to_Refund\', \'Unable_to_refund\' ) THEN \'Refund\' WHEN TAG IN ( \'Return_Query\',\'Reverse_pickup_Query \',\'Exchange_Query\', \'Re-arrange_Reverse_Pickup\',\'How to place return request\', \'Reverse_Pickup_Pending\',\'Unable to place return request\',\'Wrong_Product_Delivered\', \'Reverse_Pickup_Issue\',\'Exchange_to_Refund\',\'Product_Quality_Issue\', \'Picked Up Status not updated\',\'Return_request_placed_on_behalf_of_CX\', \'NSPC_reverse\',\'Damaged_Defective_Product\',\'RVP_Charges_Initiated\', \'RVP_Charges_Query\',\'RVP-Fake_remarks\',\'Exchange_request_placed_on_behalf_of_CX\' ) THEN \'Reverse\' ELSE \'Ignore\' END AS MASTER_QUERY FROM freshchat_frontent_old WHERE BOT_CONVERSATION_FLAG = \'No\' AND RESOLVED_AT <> \'\' AND SHOPIFY_ORDER_ID != \'\' AND SHOPIFY_ORDER_ID != \'0\' ), B AS ( SELECT s.*, ROW_NUMBER() OVER (PARTITION BY s.\"Order ID\" ORDER BY s.\"Created at\" DESC) AS rn FROM snitch_clickpost_track_order_dashboard_report s ), B_COUNT AS ( SELECT \"Order ID\", COUNT(*) AS entry_count FROM snitch_clickpost_track_order_dashboard_report GROUP BY \"Order ID\" ) SELECT A.TAG, A.STATUS, A.CHANNEL, A.CSAT_SCORE, A.RESOLVED_AT, A.INITIATED_AT, A.INTERACTION_ID, A.WAIT_TIME_BHRS, A.WAIT_TIME_CHRS, A.CONVERSATION_ID, A.SHOPIFY_ORDER_ID, A.BOT_CONVERSATION_FLAG, A.MASTER_QUERY, B.\"AWB\", B.\"ZONE\", B.\"QC Type\", B.\"RTO AWB\", B.\"Order ID\", B.\"Order Date\", B.\"Created at\", B.\"RVP Reason\", B.\"Pickup Date\", B.\"Payment Mode\", B.\"Delivery Date\", B.\"Courier Partner\", B.\"Reference Number\", B.\"Remark Of Last Pickup\", B.\"Out For Pickup Attempts\", B.\"Clickpost Unified Status\", B.\"Out For Delivery Attempts\", B.\"Out For Pickup 1st Attempt\", B.\"Out For Delivery 1st Attempt\", B.\"Expected Date of Delivery (Max)\", B_COUNT.entry_count, CASE WHEN A.MASTER_QUERY = \'Forward\' AND NULLIF(B.\"Out For Delivery 1st Attempt\", \'\') IS NOT NULL AND NULLIF(B.\"Expected Date of Delivery (Max)\", \'\') IS NOT NULL AND DATEDIFF( day, TO_TIMESTAMP(NULLIF(B.\"Out For Delivery 1st Attempt\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), TO_TIMESTAMP(NULLIF(B.\"Expected Date of Delivery (Max)\", \'\'), \'YYYY-MM-DD\') ) > 0 THEN \'Breach\' ELSE \'Nonbreach\' END AS Breach_Status FROM A LEFT JOIN B_COUNT ON A.SHOPIFY_ORDER_ID = B_COUNT.\"Order ID\" LEFT JOIN B ON A.SHOPIFY_ORDER_ID = B.\"Order ID\" AND B.rn = 1 WHERE RESOLVED_AT >= \'2024-10-01\' ); CREATE OR REPLACE TABLE customer_support_escalations_forward as ( WITH A AS ( SELECT *, CASE WHEN TAG IN ( \'Where is my order\',\'Delay_Delivery\',\'RTO\',\'My order EDD\',\'POD\', \'Tracking_Link_Status\',\'EMIZA\',\'WH2\',\'Is my order confirmed?\', \'Manifest-Issue\',\'NSPC_forward\',\'Dispatch_Delay\',\'Shipment_Lost\' ) THEN \'Forward\' WHEN TAG IN ( \'Refund_Query_Within_TAT\',\'Refund_not_Initiated\',\'General_refund_query\', \'Wallet_Refund_Query\',\'UTR\',\'Wallet_to_Refund\',\'Giftcard_to_Refund\', \'Unable_to_refund\' ) THEN \'Refund\' WHEN TAG IN ( \'Return_Query\',\'Reverse_pickup_Query \',\'Exchange_Query\', \'Re-arrange_Reverse_Pickup\',\'How to place return request\', \'Reverse_Pickup_Pending\',\'Unable to place return request\',\'Wrong_Product_Delivered\', \'Reverse_Pickup_Issue\',\'Exchange_to_Refund\',\'Product_Quality_Issue\', \'Picked Up Status not updated\',\'Return_request_placed_on_behalf_of_CX\', \'NSPC_reverse\',\'Damaged_Defective_Product\',\'RVP_Charges_Initiated\', \'RVP_Charges_Query\',\'RVP-Fake_remarks\',\'Exchange_request_placed_on_behalf_of_CX\' ) THEN \'Reverse\' ELSE \'Ignore\' END AS MASTER_QUERY FROM freshchat_frontent_old WHERE BOT_CONVERSATION_FLAG = \'No\' AND RESOLVED_AT <> \'\' AND SHOPIFY_ORDER_ID != \'\' AND SHOPIFY_ORDER_ID != \'0\' ), B AS ( SELECT s.*, ROW_NUMBER() OVER (PARTITION BY s.\"Order ID\" ORDER BY s.\"Created at\" DESC) AS rn FROM snitch_clickpost_track_order_dashboard_report s where \"Courier Partner\" IN (\'Blitz (Formerly Grow Simplee)\',\'Bluedart\',\'Delhivery\',\'Ekart Logistics\',\'Shiprocket\') ), B_COUNT AS ( SELECT \"Order ID\", COUNT(*) AS entry_count FROM snitch_clickpost_track_order_dashboard_report where \"Courier Partner\" IN (\'Blitz (Formerly Grow Simplee)\',\'Bluedart\',\'Delhivery\',\'Ekart Logistics\',\'Shiprocket\') GROUP BY \"Order ID\" ) SELECT A.TAG, A.STATUS, A.CHANNEL, A.CSAT_SCORE, A.RESOLVED_AT, A.INITIATED_AT, A.INTERACTION_ID, A.WAIT_TIME_BHRS, A.WAIT_TIME_CHRS, A.CONVERSATION_ID, A.SHOPIFY_ORDER_ID, A.BOT_CONVERSATION_FLAG, A.MASTER_QUERY, B.\"AWB\", B.\"ZONE\", B.\"QC Type\", B.\"RTO AWB\", B.\"Order ID\", B.\"Order Date\", B.\"Created at\", B.\"RVP Reason\", B.\"Pickup Date\", B.\"Payment Mode\", B.\"Delivery Date\", B.\"Courier Partner\", B.\"Reference Number\", B.\"Remark Of Last Pickup\", B.\"Out For Pickup Attempts\", B.\"Clickpost Unified Status\", B.\"Out For Delivery Attempts\", B.\"Out For Pickup 1st Attempt\", B.\"Out For Delivery 1st Attempt\", B.\"Expected Date of Delivery (Max)\", B_COUNT.entry_count, CASE WHEN A.MASTER_QUERY = \'Forward\' AND DATEDIFF( \'day\', TO_TIMESTAMP(NULLIF(B.\"Out For Delivery 1st Attempt\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), TO_TIMESTAMP(NULLIF(B.\"Expected Date of Delivery (Max)\", \'\'), \'YYYY-MM-DD\') ) > 0 THEN \'Breach\' ELSE \'Nonbreach\' END AS Breach_Status, DATEDIFF( \'day\', TO_TIMESTAMP(NULLIF(B.\"Out For Delivery 1st Attempt\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), TO_TIMESTAMP(NULLIF(B.\"Expected Date of Delivery (Max)\", \'\'), \'YYYY-MM-DD\') ) as breach_check FROM A LEFT JOIN B_COUNT ON A.SHOPIFY_ORDER_ID = B_COUNT.\"Order ID\" LEFT JOIN B ON A.SHOPIFY_ORDER_ID = B.\"Order ID\" AND B.rn = 1 WHERE MASTER_QUERY != \'Ignore\' and RESOLVED_AT >= \'2024-10-01\'); CREATE OR REPLACE TABLE customer_support_escalations_reverse as ( WITH A AS ( SELECT *, CASE WHEN TAG IN ( \'Where is my order\',\'Delay_Delivery\',\'RTO\',\'My order EDD\',\'POD\', \'Tracking_Link_Status\',\'EMIZA\',\'WH2\',\'Is my order confirmed?\', \'Manifest-Issue\',\'NSPC_forward\',\'Dispatch_Delay\',\'Shipment_Lost\' ) THEN \'Forward\' WHEN TAG IN ( \'Refund_Query_Within_TAT\',\'Refund_not_Initiated\',\'General_refund_query\', \'Wallet_Refund_Query\',\'UTR\',\'Wallet_to_Refund\',\'Giftcard_to_Refund\', \'Unable_to_refund\' ) THEN \'Refund\' WHEN TAG IN ( \'Return_Query\',\'Reverse_pickup_Query \',\'Exchange_Query\', \'Re-arrange_Reverse_Pickup\',\'How to place return request\', \'Reverse_Pickup_Pending\',\'Unable to place return request\',\'Wrong_Product_Delivered\', \'Reverse_Pickup_Issue\',\'Exchange_to_Refund\',\'Product_Quality_Issue\', \'Picked Up Status not updated\',\'Return_request_placed_on_behalf_of_CX\', \'NSPC_reverse\',\'Damaged_Defective_Product\',\'RVP_Charges_Initiated\', \'RVP_Charges_Query\',\'RVP-Fake_remarks\',\'Exchange_request_placed_on_behalf_of_CX\' ) THEN \'Reverse\' ELSE \'Ignore\' END AS MASTER_QUERY FROM freshchat_frontent_old WHERE BOT_CONVERSATION_FLAG = \'No\' AND RESOLVED_AT <> \'\' AND SHOPIFY_ORDER_ID != \'\' AND SHOPIFY_ORDER_ID != \'0\' ), B AS ( SELECT s.*, ROW_NUMBER() OVER (PARTITION BY s.\"Order ID\" ORDER BY s.\"Created at\" DESC) AS rn FROM snitch_clickpost_track_order_dashboard_report s where \"Courier Partner\" IN (\'Delhivery Reverse\',\'Proship B2C Reverse\',\'Ekart Reverse\') ), B_COUNT AS ( SELECT \"Order ID\", COUNT(*) AS entry_count FROM snitch_clickpost_track_order_dashboard_report where \"Courier Partner\" IN (\'Delhivery Reverse\',\'Proship B2C Reverse\',\'Ekart Reverse\') GROUP BY \"Order ID\" ) SELECT A.TAG, A.STATUS, A.CHANNEL, A.CSAT_SCORE, A.RESOLVED_AT, A.INITIATED_AT, A.INTERACTION_ID, A.WAIT_TIME_BHRS, A.WAIT_TIME_CHRS, A.CONVERSATION_ID, A.SHOPIFY_ORDER_ID, A.BOT_CONVERSATION_FLAG, A.MASTER_QUERY, B.\"AWB\", B.\"ZONE\", B.\"QC Type\", B.\"RTO AWB\", B.\"Order ID\", B.\"Order Date\", B.\"Created at\", B.\"RVP Reason\", B.\"Pickup Date\", B.\"Payment Mode\", B.\"Delivery Date\", B.\"Courier Partner\", B.\"Reference Number\", B.\"Remark Of Last Pickup\", B.\"Out For Pickup Attempts\", B.\"Clickpost Unified Status\", B.\"Out For Delivery Attempts\", B.\"Out For Pickup 1st Attempt\", B.\"Out For Delivery 1st Attempt\", B.\"Expected Date of Delivery (Max)\", B_COUNT.entry_count, CASE WHEN A.MASTER_QUERY = \'Forward\' AND NULLIF(B.\"Out For Delivery 1st Attempt\", \'\') IS NOT NULL AND NULLIF(B.\"Expected Date of Delivery (Max)\", \'\') IS NOT NULL AND DATEDIFF( day, TO_TIMESTAMP(NULLIF(B.\"Out For Delivery 1st Attempt\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), TO_TIMESTAMP(NULLIF(B.\"Expected Date of Delivery (Max)\", \'\'), \'YYYY-MM-DD\') ) > 0 THEN \'Breach\' ELSE \'Nonbreach\' END AS Breach_Status FROM A LEFT JOIN B_COUNT ON A.SHOPIFY_ORDER_ID = B_COUNT.\"Order ID\" LEFT JOIN B ON A.SHOPIFY_ORDER_ID = B.\"Order ID\" AND B.rn = 1 WHERE MASTER_QUERY != \'Ignore\' and RESOLVED_AT >= \'2024-10-01\');",
